/* RealMapper.selectTotal 전체 현황 - 최근 발송 시간 기준 */
DECLARE @d_date DATETIME SELECT @d_date = (SELECT TOP 1 IN_TIME FROM T_MSG_TRAFFIC GROUP BY IN_TIME ORDER BY IN_TIME DESC) SELECT ISNULL(REPLACE(SUBSTRING(CONVERT(CHAR(8), MAX(IN_TIME), 8), 4, 8), ':', ''), '00:00') AS IN_TIME , ISNULL(SUM(SEND_CNT), 0) AS SEND_CNT FROM T_MSG_TRAFFIC
WHERE IN_TIME <= DATEADD(N, 0, @d_date) AND IN_TIME >= DATEADD(N, -#{totalMonTime}, @d_date)
AND TABLE_CODE IN
#{code}

mapper.select:
/* RealMapper.selectRealHistList 옥션, G마켓 전체 테이블 현황 */
SELECT ISNULL(REPLACE(SUBSTRING(CONVERT(CHAR(8), GETDATE(), 8), 4, 8), ':', ''), '00:00') IN_TIME , ISNULL(SUM(SEND_CNT), 0) SEND_CNT , ISNULL(SUM(SUCC_CNT), 0) SUCC_CNT , ISNULL(SUM(FAIL_CNT), 0) FAIL_CNT FROM T_MSG_TRAFFIC
WHERE IN_TIME <= GETDATE() AND IN_TIME >= DATEADD(N, -1, GETDATE())
AND TABLE_CODE IN
#{code}

/* RealMapper.selectRealHistTableList 테이블별 현황 - 발송량 통계, 발송량 상세 */
WITH LATEST_TIME AS ( SELECT TABLE_CODE, MAX(IN_TIME) AS MAX_IN_TIME FROM T_MSG_TRAFFIC WHERE 1 = 1
AND TABLE_CODE IN
#{code}
GROUP BY TABLE_CODE ) SELECT T.TABLE_CODE AS TABLE_CODE, ISNULL(REPLACE(SUBSTRING(CONVERT(CHAR(8), t.IN_TIME, 8), 4, 5), ':', ''), '0000') AS IN_TIME, ISNULL(SUM(T.SEND_CNT), 0) AS SEND_CNT, ISNULL(SUM(T.SUCC_CNT), 0) AS SUCC_CNT, ISNULL(SUM(T.FAIL_CNT), 0) AS FAIL_CNT FROM T_MSG_TRAFFIC T JOIN LATEST_TIME L ON T.TABLE_CODE = L.TABLE_CODE AND T.IN_TIME = L.MAX_IN_TIME GROUP BY T.TABLE_CODE, T.IN_TIME ORDER BY T.TABLE_CODE

mapper.sql:
/* ACTIVE_SERVER 회사별 Active 서버로 조회
PROC_DATA COMPANY_CODE, SVC_NAME, PROC_NAME 그룹핑하여 1건으로 조회
STATUS_DATA 다운: UPDATE_DATE 5분 이상 초과 OR MON_TYPE = 3 이 하나라도 존재 지연: UPDATE_DATE 1~4분 초과 이슈: PROC_STS 중 하나라도 OFF(0) 정상: PROC_STS가 모두 ON (1 또는 2) 조회 우선 순위: 다운 > 지연 > 이슈 > 정상 */ WITH ACTIVE_SERVER AS ( SELECT COMPANY_CODE, SERVER_ID FROM T_SERVER_STATUS WHERE SERVER_STAT = 'A' ), PROC_DATA AS ( SELECT P.COMPANY_CODE, P.SVC_NAME, P.PROC_NAME, MAX(P.UPDATE_DATE) AS LAST_UPDATE_DATE, MIN(P.PROC_STS) AS MIN_PROC_STS, MAX(CASE WHEN P.MON_TYPE = 3 THEN 1 ELSE 0 END) AS HAS_MON3 FROM T_PROC_STATUS P JOIN ACTIVE_SERVER S ON P.COMPANY_CODE = S.COMPANY_CODE AND P.SERVER_ID = S.SERVER_ID GROUP BY P.COMPANY_CODE, P.SVC_NAME, P.PROC_NAME ), STATUS_DATA AS ( SELECT COMPANY_CODE, SVC_NAME, PROC_NAME, CASE -- 다운 WHEN DATEDIFF(MINUTE, LAST_UPDATE_DATE, GETDATE()) >= 5 OR HAS_MON3 = 1 THEN 'DOWN' -- 지연 WHEN DATEDIFF(MINUTE, LAST_UPDATE_DATE, GETDATE()) BETWEEN 1 AND 4 THEN 'DELAY' -- 이슈 WHEN MIN_PROC_STS = 0 THEN 'ISSUE' -- 정상 ELSE 'NORMAL' END AS STATUS FROM PROC_DATA )

mapper.update:
/*
	RealMapper.updateServerFlag 수동 절체 FLAG 업데이트
*/
UPDATE T_SERVER_STATUS SET
	MANUAL_FLAG = #{manualFlag}
WHERE COMPANY_CODE = #{companyCode}
